// Helper functions
func getFieldWrapperClasses(props FieldProps) string {
	classes := []string{"field"}

	// Add layout-specific classes
	if props.FieldLayout == "horizontal" {
		classes = append(classes, "field-horizontal")
	} else {
		classes = append(classes, "field-vertical", "mb-5")
	}

	// Add state classes
	if props.HasError {
		classes = append(classes, "field-error")
	} else if props.HasSuccess {
		classes = append(classes, "field-success")
	}

	// Add custom classes
	if props.Class != "" {
		classes = append(classes, props.Class)
	}

	return strings.Join(classes, " ")
}

func getFieldLabelClasses(props FieldProps) string {
	classes := []string{
		"block",
		"text-sm",
		"font-medium",
		"mb-2",
	}

	// Add state-specific colors
	if props.HasError {
		classes = append(classes, "text-red-900", "dark:text-red-400")
	} else if props.HasSuccess {
		classes = append(classes, "text-green-900", "dark:text-green-400")
	} else {
		classes = append(classes, "text-gray-900", "dark:text-white")
	}

	return strings.Join(classes, " ")
}

func getHorizontalInputColClasses(props FieldProps) string {
	if props.Label != "" && props.Type != FieldTypeCheckbox && props.Type != FieldTypeRadio && props.Type != FieldTypeToggle {
		return "md:col-span-2"
	}
	return "md:col-span-3"
}

func shouldShowFeedback(props FieldProps) bool {
	return (props.HasError && props.ErrorText != "") ||
		(props.HasSuccess && props.HelpText != "") ||
		(props.HelpText != "")
}

func getAriaDescribedBy(props FieldProps) string {
	describedBy := []string{}

	if props.AriaDescribedBy != "" {
		describedBy = append(describedBy, props.AriaDescribedBy)
	}

	if shouldShowFeedback(props) {
		if props.HasError && props.ErrorText != "" {
			describedBy = append(describedBy, getFeedbackID(props, "error"))
		} else if props.HasSuccess && props.HelpText != "" {
			describedBy = append(describedBy, getFeedbackID(props, "success"))
		} else if props.HelpText != "" {
			describedBy = append(describedBy, getFeedbackID(props, "help"))
		}
	}

	return strings.Join(describedBy, " ")
}

func getFeedbackID(props FieldProps, feedbackType string) string {
	if props.ID != "" {
		return props.ID + "-" + feedbackType
	}
	if props.Name != "" {
		return props.Name + "-" + feedbackType
	}
	return "field-" + feedbackType
}

